<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$u['id']]);$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 100');$q->execute([$u['id']]);$rows=$q->fetchAll();require __DIR__.'/../app/layout.php';header_html('Notifications');?><div class="card"><h2>Notifications</h2><?php if(!$rows):?><p class="muted">No notifications.</p><?php else:foreach($rows as $r):?><div class="notice"><strong><?=e($r['title'])?></strong><p><?=e($r['message'])?></p><small><?=e($r['created_at'])?></small></div><?php endforeach;endif;?></div><?php footer_html();
